/* theme.css */

/* Light Theme */
:root {
  /* Backgrounds */
  --color-bg-primary: #ffffff;
  --color-bg-secondary: #f5f5f5;
  --color-bg-accent: #e0e7ff;

  /* Text */
  --color-text-primary: #1a1a1a;
  --color-text-secondary: #3d3d3d;
  --color-text-inverse: #ffffff;

  /* Borders and Dividers */
  --color-border: #c0c0c0;
  --color-divider: #d6d6d6;

  /* Interactive */
  --color-link: #1a3fcc;
  --color-link-hover: #153aab;
  --color-button-bg: #1a3fcc;
  --color-button-text: #ffffff;
  --color-button-bg-hover: #153aab;

  /* Status */
  --color-success: #2e7d32; /* dark green */
  --color-error: #d32f2f;   /* dark red */
  --color-warning: #ed6c02; /* dark orange */
  --color-info: #0288d1;    /* dark blue */
}

/* Dark Theme */
[data-theme="dark"] {
  /* Backgrounds */
  --color-bg-primary: #121212;
  --color-bg-secondary: #1e1e1e;
  --color-bg-accent: #2a2a40;

  /* Text */
  --color-text-primary: #e0e0e0;
  --color-text-secondary: #b3b3b3;
  --color-text-inverse: #121212;

  /* Borders and Dividers */
  --color-border: #444444;
  --color-divider: #3a3a3a;

  /* Interactive */
  --color-link: #82aaff;
  --color-link-hover: #6699ff;
  --color-button-bg: #82aaff;
  --color-button-text: #121212;
  --color-button-bg-hover: #6699ff;

  /* Status */
  --color-success: #81c784; /* lighter green */
  --color-error: #ef5350;   /* lighter red */
  --color-warning: #ffb74d; /* lighter orange */
  --color-info: #64b5f6;    /* lighter blue */
}
